import java.nio.file.*;import java.util.*;import org.json.*;
public final class NinjagoHostCheck {
 public static void main(String[] args)throws Exception{JSONArray fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getJSONArray("fixtures"),results=new JSONArray();int passed=0;
  for(int i=0;i<fixtures.length();i++){JSONObject f=fixtures.getJSONObject(i),out=new JSONObject().put("title",f.getString("title"));NativeHttp.CURRENT.set(new NativeHttp.Session(35000));try{DozaCatalog.Located located=new DozaCatalog().locate(f.getJSONObject("data"));if(located==null||!located.pageUrl.equals(f.getString("page")))throw new Exception("Wrong address");JSONArray hosts=new JSONArray();boolean playmogo=false,vidmoly=false;for(NativeCatalog.Candidate c:DozaCatalog.players(located)){ResolvedStream s=RoDubbedProvider.resolve(c);Object link=RoDubbedProvider.makeLink(s);hosts.put(new JSONObject().put("host",c.host).put("type",link.getClass().getMethod("getType").invoke(link).toString()));if(c.host.equals("Playmogo"))playmogo=true;if(c.host.equals("Vidmoly"))vidmoly=true;}if(!playmogo||!vidmoly)throw new Exception("Missing supported host");out.put("pass",true).put("hosts",hosts);passed++;}catch(Exception e){out.put("pass",false).put("error",e.toString());}finally{NativeHttp.session().stop();NativeHttp.CURRENT.remove();}results.put(out);System.out.println(out);}
  Files.write(Paths.get(args[1]),new JSONObject().put("passed",passed).put("total",fixtures.length()).put("results",results).toString(2).getBytes("UTF-8"));System.exit(passed==fixtures.length()?0:1);
 }
}
